"""RESULTS.md for the Turbo 50k funded portfolio (python table.py)."""
import json
from pathlib import Path

R = Path(__file__).resolve().parent
L = lambda n: json.loads((R / n).read_text(encoding='utf-8'))  # noqa: E731
sel, grid, val, oos, fin, rec = L('SELECT.json'), L('GRID.json'), L('VALIDATION.json'), L('OOS.json'), L('FINAL.json'), L('RECOMMENDED.json')
usd = lambda v: '-' if v is None else f'${v:,.0f}'  # noqa: E731
pct = lambda v: '-' if v is None else f'{100 * v:.0f}%'  # noqa: E731
num = lambda v: '-' if v is None else f'{v:g}'  # noqa: E731
risks = list(fin)
md = ['# Turbo $50k funded portfolio — results (generated by table.py)', '',
      f"Recommended risk (validation rule): **{rec['risk']:g}%**. Members ({len(sel['members'])}): " + ', '.join(sel['members']), '',
      'Pessimistic breach model (balance minus all open stops). Trailing 6% floor below the highest closed balance, re-based after each reward. Rewards: 14-day cycle, '
      '≥3 days ≥ +$250, best day ≤ 20% of cycle profit, 80% share. "Frozen" = less than $25 of room above floor + buffer (the account is not breached but cannot trade).', '',
      '## Risk-management profile chosen on development (per risk level)', '',
      '| Risk / trade | $ / trade | Max open risk | Max per symbol | Daily soft stop | Trailing buffer | Room taper |', '|---:|---:|---:|---:|---:|---:|---:|']
for r in risks:
    g = fin[r]['guard']; rr = float(r)
    md.append(f"| {rr:g}% | ${rr * 500:,.0f} | {g['maxopen']:g}% (${g['maxopen'] * 500:,.0f}) | {g['persym'] * rr:g}% | {g['dstop']:g}% (${g['dstop'] * 500:,.0f}) | {g['buffer']:g}% (${g['buffer'] * 500:,.0f}) | "
              f"{'off' if not g['taper'] else f'{100 * g['taper']:.0f}% of room'} |")
md += ['', '## Funded account — 3-year Monte Carlo (1,000 paths, all-period 4-week blocks)', '',
       '| Risk | Income / day | / week | / month (median while alive) | / month (mean) | Total paid 3 y median / mean | Gross P&L / month | Payouts (median) | First payout day | No payout at all |',
       '|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in risks:
    f = fin[r]['funded_3y']
    md.append(f"| {r}% | {usd(f['income_day_median'])} | {usd(f['income_week_median'])} | {usd(f['income_month_median'])} | {usd(f['income_month_mean'])} | {usd(f['income_total_median'])} / {usd(f['income_total_mean'])} | "
              f"{usd(f['gross_month_mean'])} | {num(f['payouts_median'])} | {num(f['first_payout_day_median'])} | {pct(f['no_payout'])} |")
md += ['', '| Risk | Breach ≤ 90 d / 180 d / 1 y / 3 y | Frozen (3 y) | Median days alive | Median days to breach | Worst DD closed / stop-marked (worst; p95) | Worst day (worst; p5) | Worst week (worst; p5) | Win streak avg / max | Loss streak avg / max | Trades / month | / day |',
       '|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in risks:
    f = fin[r]['funded_3y']
    md.append(f"| {r}% | {pct(f['breach_90'])} / {pct(f['breach_180'])} / {pct(f['breach_365'])} / {pct(f['breach'])} | {pct(f['freeze'])} | {num(f['days_alive_median'])} | {num(f['days_to_breach_median'])} | "
              f"{usd(f['dd_closed_worst'])} / {usd(f['dd_stop_worst'])} ({usd(f['dd_closed_p95'])}; {usd(f['dd_stop_p95'])}) | {usd(f['worst_day'])} ({usd(f['worst_day_p5'])}) | {usd(f['worst_week'])} ({usd(f['worst_week_p5'])}) | "
              f"{f['win_streak_avg']} / {num(f['win_streak_max'])} | {f['loss_streak_avg']} / {num(f['loss_streak_max'])} | {f['trades_per_month']} | {f['trades_per_day']} |")
md += ['', '## Funded account — first 12 months: Monte Carlo vs real history (every weekday start 2021-10 → 2025-10)', '',
       '| Risk | Income / month median MC / hist | Total 12 m median MC / hist | Mean MC / hist | No payout MC / hist | Frozen ≤ 1 y MC / hist | Breach ≤ 1 y MC / hist | Worst day MC / hist | Worst week MC / hist |',
       '|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in risks:
    m, h = fin[r]['funded_1y'], fin[r]['funded_1y_hist']
    md.append(f"| {r}% | {usd(m['income_month_median'])} / {usd(h['income_month_median'])} | {usd(m['income_total_median'])} / {usd(h['income_total_median'])} | {usd(m['income_total_mean'])} / {usd(h['income_total_mean'])} | "
              f"{pct(m['no_payout'])} / {pct(h['no_payout'])} | {pct(m['freeze'])} / {pct(h['freeze'])} | {pct(m['breach_365'])} / {pct(h['breach_365'])} | {usd(m['worst_day'])} / {usd(h['worst_day'])} | {usd(m['worst_week'])} / {usd(h['worst_week'])} |")
md += ['', '## By window — 12-month trader income (MC median / mean; pessimistic)', '', '| Risk | Development 2021–23 | Validation 2023–24 | OOS 2024–26 (previously viewed) | OOS history median |', '|---:|---:|---:|---:|---:|']
for r in risks:
    d = grid[r]['chosen']['dev']; v = val[r]['mc']; o = oos[r]['mc']; oh = oos[r]['hist']
    md.append(f"| {r}% | {usd(d['income_total_median'])} / {usd(d['income_total_mean'])} | {usd(v['income_total_median'])} / {usd(v['income_total_mean'])} | {usd(o['income_total_median'])} / {usd(o['income_total_mean'])} | {usd(oh['income_total_median'])} |")
md += ['', '## Sensitivities (3-year MC unless noted)', '', '| Risk | Trailing floor (base): income / month mean, frozen | STATIC 6% floor: income / month mean, frozen, breach | Static floor history 12 m median | 5-day reward cycle (12 m mean) | 95% share (12 m mean) | Optimistic breach model: frozen / breach |',
       '|---:|---:|---:|---:|---:|---:|---:|']
for r in risks:
    f, s, sh, d5, s95, op = fin[r]['funded_3y'], fin[r]['funded_3y_static_floor'], fin[r]['funded_1y_hist_static_floor'], fin[r]['funded_1y_5day'], fin[r]['funded_1y_95'], fin[r]['funded_3y_optimistic']
    md.append(f"| {r}% | {usd(f['income_month_mean'])}, {pct(f['freeze'])} | {usd(s['income_month_mean'])}, {pct(s['freeze'])}, {pct(s['breach'])} | {usd(sh['income_total_median'])} | {usd(d5['income_total_mean'])} | {usd(s95['income_total_mean'])} | {pct(op['freeze'])} / {pct(op['breach'])} |")
md += ['', '## Evaluation phase (for new accounts): +6% target, 3% daily, 6% trailing, same profile', '', '| Risk | Pass MC / hist | Pass ≤ 30 d / 60 d / 90 d (MC) | Median days to pass MC / hist | Breach MC | Frozen MC |', '|---:|---:|---:|---:|---:|---:|']
for r in risks:
    e, eh = fin[r]['evaluation'], fin[r]['evaluation_hist']
    md.append(f"| {r}% | {pct(e['pass_rate'])} / {pct(eh['pass_rate'])} | {pct(e['pass_30'])} / {pct(e['pass_60'])} / {pct(e['pass_90'])} | {num(e['median_days'])} / {num(eh['median_days'])} | {pct(e['breach'])} | {pct(e['freeze'])} |")
(R / 'RESULTS.md').write_text('\n'.join(md) + '\n', encoding='utf-8'); print('RESULTS.md')
